import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"The LLM Mental Model (Bridge)","description":"An LLM is a parametrized conditional probability model predicting one token at a time — this single mental model determines what prompts really do, why the context window is a hard constraint, and why temperature is not a creativity knob; derivations and implementations belong to Learn LLM.","frontmatter":{"title":"The LLM Mental Model (Bridge)","description":"An LLM is a parametrized conditional probability model predicting one token at a time — this single mental model determines what prompts really do, why the context window is a hard constraint, and why temperature is not a creativity knob; derivations and implementations belong to Learn LLM.","domain":"tech","tags":["tech","model-lifecycle","bridge","mental-model"],"navOrder":11,"topicId":"llm-mental-model","layer":"1","status":"bridge","nodeType":"concept","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/chapters/04-probabilistic-lm"}],"prerequisites":["model-lifecycle-bridge"],"next":["architecture"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/01-model-lifecycle/llm-mental-model.md","filePath":"tech/01-model-lifecycle/llm-mental-model.md","lastUpdated":1791123021000}'),o={name:"tech/01-model-lifecycle/llm-mental-model.md"};function n(s,t,l,d,h,c){return r(),a("div",null,[...t[0]||(t[0]=[i('<blockquote><p><strong>Group</strong>: 01 · Model Lifecycle (bridge group) | <strong>Exit of the group above</strong>: you can decide knowledge ownership and pick the lowest-complexity option for a need (00-map group) | <strong>Exit of this page</strong>: you can explain what prompts, context, and temperature really do using &quot;parametrized conditional probability model&quot;, and you hold a correct expectation of hallucination <strong>Prerequisites</strong>: <a href="./index.html">Model Lifecycle (group guide)</a> | <strong>Next</strong>: <a href="./architecture.html">Model Architecture (Bridge)</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>Lead with the answer</strong>: a large language model (LLM) is a <strong>parametrized conditional probability model</strong> — a set of weights trained on massive text that, given a prefix of tokens, outputs a probability distribution over the next token, samples from it, and loops. This definition is not academic decoration: every engineering judgment you make about prompt strategy, context budget, hallucination, and model selection is a corollary of it. This page only builds that mental model and maps which decisions it touches; the from-scratch implementation and loss-function derivations belong to <a href="https://llm.zenheart.site/chapters/04-probabilistic-lm" target="_blank" rel="noreferrer">Learn LLM chapter 4</a>.</p><h3 id="three-direct-corollaries" tabindex="-1">Three direct corollaries <a class="header-anchor" href="#three-direct-corollaries" aria-label="Permalink to &quot;Three direct corollaries&quot;">​</a></h3><ol><li><strong>A prompt invokes capability; it does not inject knowledge.</strong> Capability is fixed into the weights during training; a prompt selects which capabilities activate and in what format. The only reliable channel for making the model &quot;know&quot; a fact absent from its training data is putting the fact into context (<a href="./../03-context/">03-context group</a>) or retrieval (<a href="./../04-grounding/rag.html">RAG</a>) — not repeating it insistently in instructions.</li><li><strong>The context window is a hard constraint.</strong> The model conditions only on tokens inside the current context; anything beyond it is not &quot;remembered&quot;, and you must carry session history explicitly and pay for it. Context engineering is therefore a discipline of trade-offs, not &quot;fill it up&quot;.</li><li><strong>Temperature is a sampling parameter, not a creativity knob.</strong> It flattens or sharpens the next-token sampling distribution: low temperature favors high-probability tokens (more stable), high temperature is more random (more diverse). It reshapes the output distribution; it cannot make the model produce correct answers beyond what the weights support — it does not fix capability problems.</li></ol><h3 id="correcting-three-common-misconceptions" tabindex="-1">Correcting three common misconceptions <a class="header-anchor" href="#correcting-three-common-misconceptions" aria-label="Permalink to &quot;Correcting three common misconceptions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Misconception</th><th>Correction</th></tr></thead><tbody><tr><td>LLM = ChatGPT</td><td>ChatGPT is a product: LLM + post-training + system prompt + tooling and UI wrapping; the same model behaves differently in different products</td></tr><tr><td>LLM = RAG</td><td>RAG is an application-layer retrieval pattern; the model itself does not retrieve — the two combine often but are orthogonal</td></tr><tr><td>LLM = Agent</td><td>An agent is an orchestration loop (plan-act-observe) that calls a model; the model is only the reasoning part of the loop</td></tr></tbody></table><p>The dividing lines are detailed in <a href="./../00-map/site-boundaries.html">Site Boundaries</a>; agent orchestration belongs to the 06-agent-systems group.</p><h2 id="_2-when-to-hop" tabindex="-1">2. When to Hop <a class="header-anchor" href="#_2-when-to-hop" aria-label="Permalink to &quot;2. When to Hop&quot;">​</a></h2><p>This page has no runnable artifact; the substitute action is routing your symptom to the right owner via this table:</p><table tabindex="0"><thead><tr><th>Symptom / question</th><th>Where to go</th><th>Why</th></tr></thead><tbody><tr><td>Want the math of &quot;predicting the next token&quot;, what loss is</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/04-probabilistic-lm" target="_blank" rel="noreferrer">chapter 4</a></td><td>The canonical derivation of conditional-probability language models</td></tr><tr><td>What tokens are, why billing is per token</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/05-bpe" target="_blank" rel="noreferrer">chapter 5</a></td><td>BPE tokenization from scratch</td></tr><tr><td>How to tune temperature / top-p</td><td>This repo&#39;s <a href="./../03-context/prompt.html">Prompt Engineering</a></td><td>Application-layer parameter strategy lives here</td></tr><tr><td>The model won&#39;t reliably emit JSON</td><td>This repo&#39;s <a href="./../02-inference-interface/structured-output.html">Structured Output</a></td><td>It is an interface-contract problem, not a comprehension problem</td></tr><tr><td>The model &quot;doesn&#39;t know&quot; a fact that appeared after training</td><td>This repo&#39;s <a href="./../04-grounding/rag.html">RAG</a></td><td>Missing knowledge goes through retrieval, not prompts</td></tr></tbody></table><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><p>One-paragraph positioning: the training objective of an LLM maximizes the likelihood of the next token over the training corpus; capability is a statistical regularity that emerges from the data distribution and scale, not rules written one by one. That is all the principles an engineer needs — cross-entropy, sampling strategy, and the Bigram-to-Transformer progression have complete from-scratch derivations in Learn LLM chapters 4–5 (retrievedAt 2026-09-01); this repo does not keep a second copy.</p><h2 id="_4-engineering-decision-impact" tabindex="-1">4. Engineering Decision Impact <a class="header-anchor" href="#_4-engineering-decision-impact" aria-label="Permalink to &quot;4. Engineering Decision Impact&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Engineering decision</th><th>Judgment derived from the mental model</th><th>Cost of the wrong expectation</th></tr></thead><tbody><tr><td>Model selection</td><td>Capability is fixed in the weights; sizes within a family are points on a capability-cost curve — select per task tier</td><td>Running every task on the largest model; the bill runs away</td></tr><tr><td>Prompt strategy</td><td>Instructions invoke and format existing capability; facts go into context</td><td>Baking knowledge into long instructions: unstable, non-updatable, re-billed per token</td></tr><tr><td>Context budget</td><td>Context is the only input channel and it is billed; history needs pruning and summarization</td><td>Concatenating session history wholesale; cost and latency degrade with it</td></tr><tr><td>Hallucination expectation</td><td>A probability model can generate fluent continuations that are not true; it is a product of the mechanism — managed, not &quot;prompted away&quot;</td><td>Expecting one &quot;do not fabricate&quot; line to replace grounding and evaluation</td></tr><tr><td>Output stability</td><td>Temperature reshapes the distribution, not the capability ceiling</td><td>Fixing format problems with temperature (correct fix: structured output or a better prompt)</td></tr></tbody></table><p>Maintenance rule (in place of runbooks): when Learn LLM chapters 4/5 change structure, re-verify this page&#39;s deep links and update <code>lastVerified</code>; when a new application-decision topic lands in this repo, add one row to the table above instead of expanding the principles.</p><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Four-level reading route:</p><table tabindex="0"><thead><tr><th>Level</th><th>What to read</th><th>Why this order</th></tr></thead><tbody><tr><td>Beginner</td><td>This page + the <a href="./index.html">group guide</a></td><td>Build the two chains and one mental model first</td></tr><tr><td>Builder</td><td>This repo&#39;s <a href="./../03-context/prompt.html">Prompt Engineering</a> + <a href="./../02-inference-interface/structured-output.html">Structured Output</a></td><td>Turn the mental model into interface contracts</td></tr><tr><td>Operator</td><td><a href="./../04-grounding/rag.html">RAG</a> + <a href="./../08-production/evaluation.html">Evaluation</a></td><td>Manage hallucination with grounding and evaluation</td></tr><tr><td>Researcher</td><td>Learn LLM chapters 4–5 + the GPT-3 paper</td><td>Descend to the original account of probabilistic models and in-context learning</td></tr></tbody></table><h3 id="resource-table" tabindex="-1">Resource table <a class="header-anchor" href="#resource-table" aria-label="Permalink to &quot;Resource table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Level</th><th>Canonical URL</th><th>Supported claim</th><th>Next</th></tr></thead><tbody><tr><td>Learn LLM ch. 4 · Character language model</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/04-probabilistic-lm" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/04-probabilistic-lm</a></td><td>Conditional probability and sampling are the core mechanism of LLMs</td><td>Hand-write Bigram → MLP</td></tr><tr><td>Learn LLM ch. 5 · BPE</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/05-bpe" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/05-bpe</a></td><td>The token is the unit of billing and context</td><td>Understand token cost structure</td></tr><tr><td>Learn LLM ch. 15 · Prompt and memory</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/15-prompt-memory</a></td><td>A systematic treatment of application-side prompt strategy</td><td>Compare with this repo&#39;s 03-context group</td></tr><tr><td>GPT-3 paper (Language Models are Few-Shot Learners)</td><td>L4</td><td><a href="https://arxiv.org/abs/2005.14165" target="_blank" rel="noreferrer">https://arxiv.org/abs/2005.14165</a></td><td>The original evidence that prompts invoke pretrained capability (in-context learning)</td><td>Read the few-shot sections</td></tr></tbody></table><p>(Learn LLM chapters verified via its chapter index; arXiv links are stable abs URLs; retrievedAt 2026-09-01.)</p><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>Falsification entry: if an engineering judgment truly requires sampling math or loss-function detail (e.g. implementing constrained decoding yourself), it belongs to Learn LLM or this repo&#39;s 02-inference-interface group, not this page — sink the claim to the right owner instead of expanding here.</li><li>Open: the system-prompt and tooling-wrap details in the &quot;ChatGPT product&quot; correction drift with vendor iterations and are not item-verified; treat it as a directional correction only.</li></ul><h3 id="where-learn-ai-stops-where-to-continue" tabindex="-1">Where learn-ai stops / where to continue <a class="header-anchor" href="#where-learn-ai-stops-where-to-continue" aria-label="Permalink to &quot;Where learn-ai stops / where to continue&quot;">​</a></h3><ul><li>Derivations and implementation of probabilistic language models: Learn LLM <a href="https://llm.zenheart.site/chapters/04-probabilistic-lm" target="_blank" rel="noreferrer">chapter 4</a> — this repo stops here.</li><li>Build interfaces with this mental model: this repo&#39;s <a href="./../02-inference-interface/">02-inference-interface group</a>.</li><li>Next page in this group: <a href="./architecture.html">Model Architecture (Bridge)</a>.</li></ul>',26)])])}const f=e(o,[["render",n]]);export{b as __pageData,f as default};
